-- U.E. PAULO FREIRE - Esquema v5 Final
CREATE DATABASE IF NOT EXISTS ue_paulo_freire CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ue_paulo_freire;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS users, courses, subjects, students, user_students, teacher_subjects, course_advisors, schedules, attendance, tardies, calendar_events, announcements, grades, notifications, audit_logs, login_attempts, settings, terms;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(180) NULL, email VARCHAR(180) NULL, avatar VARCHAR(255) NULL, role ENUM('admin','secretaria','docente','estudiante','padre') NOT NULL, is_asesor TINYINT(1) DEFAULT 0, language VARCHAR(5) DEFAULT 'es', theme VARCHAR(10) DEFAULT 'dark', active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE courses (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, parallel VARCHAR(10) NOT NULL, level VARCHAR(60) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE terms (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, start_date DATE NULL, end_date DATE NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, first_name VARCHAR(120) NOT NULL, last_name VARCHAR(120) NOT NULL, rude VARCHAR(80) NULL, ci VARCHAR(60) NULL, birth_date DATE NULL, gender ENUM('M','F') NULL, address VARCHAR(255) NULL, enrollment_year INT NULL, course_id INT NULL, guardian_name VARCHAR(180) NULL, guardian_phone VARCHAR(80) NULL, guardian_email VARCHAR(180) NULL, observations TEXT NULL, status TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_students (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, student_id INT NOT NULL, relation VARCHAR(80) NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE teacher_subjects (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE course_advisors (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, course_id INT NOT NULL, assigned_by INT NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE schedules (id INT AUTO_INCREMENT PRIMARY KEY, course_id INT NOT NULL, subject_id INT NOT NULL, teacher_user_id INT NULL, day_of_week VARCHAR(20) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, classroom VARCHAR(80) NULL, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE, FOREIGN KEY (teacher_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE attendance (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, attendance_date DATE NOT NULL, status ENUM('P','F','R','L','RC') NOT NULL DEFAULT 'P', reason TEXT NULL, observation TEXT NULL, registered_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_student_date (student_id, attendance_date), FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (registered_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tardies (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, tardy_date DATE NOT NULL, arrival_time TIME NULL, course_id INT NULL, teacher_user_id INT NULL, justification TEXT NULL, status VARCHAR(30) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE calendar_events (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT NULL, event_date DATE NULL, event_type VARCHAR(60) NULL, target_course_id INT NULL, responsible VARCHAR(180) NULL, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (target_course_id) REFERENCES courses(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE announcements (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, content TEXT NULL, target_type ENUM('global','course','student','teacher_area','advisor','subject') NOT NULL DEFAULT 'global', course_id INT NULL, student_id INT NULL, subject_id INT NULL, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE grades (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, subject_id INT NOT NULL, term_id INT NULL, score DECIMAL(5,2) NULL, observation TEXT NULL, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE, FOREIGN KEY (term_id) REFERENCES terms(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(180) NOT NULL, message TEXT NULL, type VARCHAR(50) NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(120) NULL, entity VARCHAR(120) NULL, entity_id INT NULL, ip VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE login_attempts (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(120) NULL, ip VARCHAR(45) NULL, success TINYINT(1) DEFAULT 0, attempted_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE VIEW v_attendance_stats AS SELECT s.id AS student_id, CONCAT(s.first_name, ' ', s.last_name) AS student, SUM(a.status = 'P') AS presentes, SUM(a.status = 'F') AS faltas, SUM(a.status = 'R') AS retrasos, SUM(a.status IN ('L','RC')) AS licencias_retirados, COUNT(a.id) AS total FROM students s LEFT JOIN attendance a ON a.student_id = s.id GROUP BY s.id;
CREATE VIEW v_student_report AS SELECT g.id, CONCAT(s.first_name, ' ', s.last_name) AS student, sub.name AS subject, t.name AS term_name, g.score, g.observation FROM grades g INNER JOIN students s ON s.id = g.student_id INNER JOIN subjects sub ON sub.id = g.subject_id LEFT JOIN terms t ON t.id = g.term_id;

DELIMITER //
CREATE PROCEDURE sp_register_attendance(IN p_student INT, IN p_date DATE, IN p_status VARCHAR(2), IN p_reason TEXT, IN p_obs TEXT, IN p_by INT)
BEGIN
  INSERT INTO attendance (student_id, attendance_date, status, reason, observation, registered_by) VALUES (p_student, p_date, p_status, p_reason, p_obs, p_by) ON DUPLICATE KEY UPDATE status = p_status, reason = p_reason, observation = p_obs, registered_by = p_by;
  IF p_status IN ('F', 'R', 'L', 'RC') THEN
    INSERT INTO notifications (user_id, title, message, type, created_at) SELECT us.user_id, 'Registro de asistencia', CONCAT('El/La estudiante registra: ', p_status, ' el ', p_date, '. Motivo: ', COALESCE(p_reason, 'Sin motivo')), 'attendance', NOW() FROM user_students us WHERE us.student_id = p_student;
  END IF;
END//
DELIMITER ;

